"""Writes kaggle/cells_stage_a/cell1_setup.py with scripts/datasets/{decontam,stage_a}.py embedded (re-run after
editing either module, so the notebook always carries the tested code)."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
mods = {name: (ROOT / "scripts" / "datasets" / name).read_text() for name in ("decontam.py", "stage_a.py")}
cell = '''# 1. STAGE A setup (CPU session, INTERNET ON, no GPU). Writes the data-prep code to /kaggle/working/code and checks
#    the tools it needs. Generated by scripts/datasets/make_stage_a_cells.py from the tested repo modules.
import importlib.util, os, shutil, subprocess, sys, urllib.request
from pathlib import Path

CODE = Path('/kaggle/working/code')
CODE.mkdir(parents=True, exist_ok=True)
FILES = {
'''
for name, text in mods.items():
    cell += f"    {name!r}: {text!r},\n"
cell += '''}
for name, text in FILES.items():
    (CODE / name).write_text(text)
for pkg in ('huggingface_hub', 'pyarrow'):
    if importlib.util.find_spec(pkg) is None:
        subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', pkg], check=True)
assert shutil.which('git'), 'git is needed for the workspace trees'
try:
    urllib.request.urlopen('https://huggingface.co', timeout=20)
except Exception as e:
    raise SystemExit(f'No internet: turn it on in the notebook settings ({e})')
r = subprocess.run([sys.executable, str(CODE / 'decontam.py'), '--test'], capture_output=True, text=True)
print(r.stdout.strip() or r.stderr[-500:])
print('code written to', CODE, '| ready')
'''
(ROOT / "kaggle" / "cells_stage_a" / "cell1_setup.py").write_text(cell)
print("wrote kaggle/cells_stage_a/cell1_setup.py")

# --- export notebook: one cell, stats for selection ---
exp = (ROOT / "scripts" / "datasets" / "export_stats.py").read_text()
cell = f'''# STAGE A EXPORT (CPU session; internet not needed). Inputs to attach: the two finished stage A notebook outputs
#   (dataset-loader-test-resume and dataset-loader-test-2-resume) and the model google/gemma-4 ->
#   gemma-4-31b-it-qat-w4a16-ct (only its tokenizer.json is read). Writes /kaggle/working/stats.jsonl.gz: one small
#   row per episode for selection. Nothing is deleted; the episodes stay where they are.
# Generated by scripts/datasets/make_stage_a_cells.py from the tested scripts/datasets/export_stats.py.
import glob, subprocess, sys
from pathlib import Path

Path('/kaggle/working/code').mkdir(parents=True, exist_ok=True)
Path('/kaggle/working/code/export_stats.py').write_text({exp!r})
ep_dirs = sorted({{str(Path(p).parent) for p in glob.glob('/kaggle/input/**/stage_a/episodes_*.jsonl', recursive=True)}})
print('episode folders:', ep_dirs)
assert len(ep_dirs) == 2, 'attach BOTH finished stage A outputs (the two *-resume notebooks)'
tok = sorted(glob.glob('/kaggle/input/models/google/gemma-4/**/tokenizer.json', recursive=True))
assert tok, 'attach the gemma-4 31B model (for its tokenizer)'
r = subprocess.run([sys.executable, '-u', '/kaggle/working/code/export_stats.py', '--episodes', *ep_dirs,
                    '--tokenizer', str(Path(tok[-1]).parent), '--out', '/kaggle/working/stats.jsonl.gz'])
print('exit code', r.returncode, '| download /kaggle/working/stats.jsonl.gz')
'''
(ROOT / "kaggle" / "cells_stage_a" / "export_stats_cell.py").write_text(cell)
print("wrote kaggle/cells_stage_a/export_stats_cell.py")
